extern crate ron;

use std::f64;
use std::i64;

use ron::de::from_str;

#[test]
fn test_whitespace() {
    assert_eq!(
        from_str("(1 + 2) * 3 = 9").unwrap_err(),
        ron::de::Error::Parser(
            ron::de::ParseError::ExpectedIdentifier,
            ron::de::Position { line: 1, col: 1 },
        ),
    );
}

#[test]
fn test_no_whitespace() {
    let tuple: (i32, f32) = from_str("(1,2)").unwrap();
    assert_eq!(tuple, (1, 2.0));
}

#[test]
fn test_float_no_whitespace() {
    let tuple: (f32, f32) = from_str("(1.0,2.0)").unwrap();
    assert_eq!(tuple, (1.0, 2.0));
}

#[test]
fn test_integers() {
    let tuple: (i32, i32, i32, i32) = from_str("(1, 2, 3, 4)").unwrap();
    assert_eq!(tuple, (1, 2, 3, 4));
}

#[test]
fn test_floats() {
    let tuple: (f32, f32, f32, f32) = from_str("(1.0, 2.0, 3.0, 4.0)").unwrap();
    assert_eq!(tuple, (1.0, 2.0, 3.0, 4.0));
}

#[test]
fn test_underscores() {
    let tuple: (i32, i32, i32, i32) = from_str("(1_000, 2_000, 3_000, 4_000)").unwrap();
    assert_eq!(tuple, (1_000, 2_000, 3_000, 4_000));
}

#[test]
fn test_float_underscores() {
    let tuple: (f32, f32, f32, f32) =
        from_str("(1_000.0, 2_000.0, 3_000.0, 4_000.0)").unwrap();
    assert_eq!(tuple, (1_000.0, 2_000.0, 3_000.0, 4_000.0));
}

#[test]
fn test_hex_underscores() {
    let tuple: (i32, i32, i32, i32) =
        from_str("(0x1_0, 0b1_0, 0o1_0, 0x1_0)").unwrap();
    assert_eq!(tuple, (0x10, 0b10, 0o10, 0x10));
}

