   246	
   247	        if (\is_resource($value)) {
   248	            return 'Resource ' . get_resource_type($value);
   249	        }
   250	
   251	        if (\is_callable($value)) {
   252	            return $this->serializeCallable($value);
   253	        }
   254	
   255	        if (\is_array($value)) {
   256	            return 'Array of length ' . \count($value);
   257	        }
   258	
   259	        return $this->serializeString($value);
   260	    }
   261	
   262	    /**
   263	     * @param callable|mixed $callable
   264	     */
   265	    protected function serializeCallable($callable): string
   266	    {
   267	        if (\is_string($callable) && !\function_exists($callable)) {
   268	            return $callable;
   269	        }
   270	
   271	        if (!\is_callable($callable)) {
   272	            throw new InvalidArgumentException(sprintf('Expecting callable, got %s', \is_object($callable) ? \get_class($callable) : \gettype($callable)));
   273	        }
   274	
   275	        try {
   276	            if (\is_array($callable)) {
   277	                $reflection = new \ReflectionMethod($callable[0], $callable[1]);
   278	                $class = $reflection->getDeclaringClass();
   279	            } elseif ($callable instanceof \Closure || (\is_string($callable) && \function_exists($callable))) {
   280	                $reflection = new \ReflectionFunction($callable);
   281	                $class = null;
   282	            } elseif (\is_object($callable) && method_exists($callable, '__invoke')) {
   283	                $reflection = new \ReflectionMethod($callable, '__invoke');
   284	                $class = $reflection->getDeclaringClass();
   285	            } else {
   286	                throw new \InvalidArgumentException('Unrecognized type of callable');
   287	            }
   288	        } catch (\ReflectionException $exception) {
   289	            return '{unserializable callable, reflection error}';
   290	        }
   291	
   292	        $callableType = $reflection->isClosure() ? 'Lambda ' : 'Callable ';
   293	        $callableReturnType = $reflection->getReturnType();
   294	
   295	        if ($callableReturnType instanceof \ReflectionNamedType) {
   296	            $callableType .= $callableReturnType->getName() . ' ';
   297	        }
   298	
   299	        if ($class) {
   300	            $callableType .= $class->getName() . '::';
   301	        }
   302	
   303	        return $callableType . $reflection->getName() . ' ' . $this->serializeCallableParameters($reflection);
   304	    }
   305	
   306	    private function serializeCallableParameters(\ReflectionFunctionAbstract $reflection): string
   307	    {
   308	        $params = [];
   309	        foreach ($reflection->getParameters() as &$param) {
   310	            $reflectionType = $param->getType();
   311	            if ($reflectionType instanceof \ReflectionNamedType) {
   312	                $paramType = $reflectionType->getName();
   313	            } else {
   314	                $paramType = 'mixed';
   315	            }
   316	
   317	            if ($param->allowsNull()) {
   318	                $paramType .= '|null';
   319	            }
   320	
   321	            $paramName = ($param->isPassedByReference() ? '&' : '') . $param->getName();
   322	
   323	            if ($param->isOptional()) {
   324	                $paramName = '[' . $paramName . ']';
   325	            }
   326	
   327	            $params[] = $paramType . ' ' . $paramName;
   328	        }
   329	
   330	        return '[' . implode('; ', $params) . ']';
   331	    }
