package testhttp

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"

	"github.com/go-bdd/gobdd/context"
	"github.com/go-bdd/gobdd/step"
)

type addStepper interface {
	AddStep(step interface{}, f step.Func) error
}

type testHTTPMethods struct {
	tHTTP TestHTTP
}

type httpResponse struct{}

// RequestKey is a marker type for storing and retrieving the current *http.Request in the BDD context.
type RequestKey struct{}

// ResponseKey is a marker type for storing and retrieving the HTTP Response in the BDD context.
type ResponseKey struct{}

func Build(addStep addStepper, h httpHandler) TestHTTP {
	thhtp := TestHTTP{
		handler: h,
	}

	testHTTP := testHTTPMethods{tHTTP: thhtp}

	_ = addStep.AddStep(`^I (?:set the header "([^"]*)" to "([^"]*)"|the header "([^"]*)" equals to "([^"]*)")$`, testHTTP.handleHeaderStep)
	_ = addStep.AddStep(`^I set the request body to "([^"]*)"$`, testHTTP.iSetRequestBodyTo)
	_ = addStep.AddStep(`^the request has body "([^"]*)"$`, testHTTP.theRequestHasBody)
	_ = addStep.AddStep(`^I have a (GET|POST|PUT|DELETE|OPTIONS) request to "([^"]*)"$`, testHTTP.iHaveARequest)
	_ = addStep.AddStep(`^I make a request$`, testHTTP.iMakeRequest)
	_ = addStep.AddStep(`^I make a (GET|POST|PUT|DELETE|OPTIONS) request to "([^"]*)"$`, testHTTP.makeRequest)
	_ = addStep.AddStep(`^the response code equals (\d+)$`, testHTTP.statusCodeEquals)
	_ = addStep.AddStep(`^the response contains a valid JSON$`, testHTTP.validJSON)
	_ = addStep.AddStep(`^the response is "(.*)"$`, testHTTP.theResponseIs)

	return thhtp
}

func (t testHTTPMethods) handleHeaderStep(ctx context.Context) error {
	setHeader := ctx.GetStringParam(0)
	if setHeader != "" {
		name := ctx.GetStringParam(1)
		value := ctx.GetStringParam(2)
		req := ctx.Get(RequestKey{}).(*http.Request)
		req.Header.Set(name, value)
		ctx.Set(RequestKey{}, req)
		return nil
	}
	name := ctx.GetStringParam(1)
	expected := ctx.GetStringParam(2)
	resp := ctx.Get(ResponseKey{}).(Response)
	if resp.Header.Get(name) != expected {
		return ctx.Assert.Equals(expected, resp.Header.Get(name))
	}
	return nil
}

func (t testHTTPMethods) iSetRequestBodyTo(ctx context.Context) error {
	body := ctx.GetStringParam(0)
	req := ctx.Get(RequestKey{}).(*http.Request)
	req.Body = io.NopCloser([]byte(body))
	ctx.Set(RequestKey{}, req)
	return nil
}

func (t testHTTPMethods) theRequestHasBody(ctx context.Context) error {
	expected := ctx.GetStringParam(0)
	req := ctx.Get(RequestKey{}).(*http.Request)
	req.Body = io.NopCloser([]byte(expected))
	ctx.Set(RequestKey{}, req)
	return nil
}

func (t testHTTPMethods) iHaveARequest(ctx context.Context) error {
	method := ctx.GetStringParam(0)
	url := ctx.GetStringParam(1)
	req, err := http.NewRequest(method, url, nil)
	if err != nil {
		return err
	}
	ctx.Set(RequestKey{}, req)
	return nil
}

func (t testHTTPMethods) iMakeRequest(ctx context.Context) error {
	req := ctx.Get(RequestKey{}).(*http.Request)
	resp, err := t.tHTTP.MakeRequest(req)
	if err != nil {
		return err
	}
	ctx.Set(ResponseKey{}, resp)
	return nil
}

func (t testHTTPMethods) theResponseIs(ctx context.Context) error {
	expectedResponse := ctx.GetStringParam(0)

	resp := ctx.Get(ResponseKey{}).(Response)
	body, err := io.ReadAll(resp.Body)
	resp.Body = io.NopCloser(bytes.NewBuffer(body))
	ctx.Set(ResponseKey{}, resp)
	if err != nil {
		return fmt.Errorf("an error while reading the body: %s", err)
