   167	func (c *microsoftConnector) HandleCallback(s connector.Scopes, r *http.Request) (identity connector.Identity, err error) {
   168		q := r.URL.Query()
   169		if errType := q.Get("error"); errType != "" {
   170			return identity, &oauth2Error{errType, q.Get("error_description")}
   171		}
   172	
   173		oauth2Config := c.oauth2Config(s)
   174	
   175		ctx := r.Context()
   176	
   177		token, err := oauth2Config.Exchange(ctx, q.Get("code"))
   178		if err != nil {
   179			return identity, fmt.Errorf("microsoft: failed to get token: %v", err)
   180		}
   181	
   182		client := oauth2Config.Client(ctx, token)
   183	
   184		user, err := c.user(ctx, client)
   185		if err != nil {
   186			return identity, fmt.Errorf("microsoft: get user: %v", err)
   187		}
   188	
   189		if c.emailToLowercase {
   190			user.Email = strings.ToLower(user.Email)
   191		}
   192	
   193		identity = connector.Identity{
   194			UserID:        user.ID,
   195			Username:      user.Name,
   196			Email:         user.Email,
   197			EmailVerified: true,
   198		}
   199	
   200		if c.groupsRequired(s.Groups) {
   201			groups, err := c.getGroups(ctx, client, user.ID)
   202			if err != nil {
   203				return identity, fmt.Errorf("microsoft: get groups: %v", err)
   204			}
   205			identity.Groups = groups
   206		}
   207	
   208		if s.OfflineAccess {
   209			data := connectorData{
   210				AccessToken:  token.AccessToken,
   211				RefreshToken: token.RefreshToken,
   212				Expiry:       token.Expiry,
   213			}
   214			connData, err := json.Marshal(data)
   215			if err != nil {
   216				return identity, fmt.Errorf("microsoft: marshal connector data: %v", err)
   217			}
   218			identity.ConnectorData = connData
   219		}
   220	
   221		return identity, nil
   222	}
