   226	// notifyRefreshTokenSource is essentially `oauth2.ReuseTokenSource` with `TokenNotifyFunc` added.
   227	type notifyRefreshTokenSource struct {
   228		new oauth2.TokenSource
   229		mu  sync.Mutex // guards t
   230		t   *oauth2.Token
   231		f   tokenNotifyFunc // called when token refreshed so new refresh token can be persisted
   232	}
   233	
   234	// Token returns the current token if it's still valid, else will
   235	// refresh the current token (using r.Context for HTTP client
   236	// information) and return the new one.
   237	func (s *notifyRefreshTokenSource) Token() (*oauth2.Token, error) {
   238		s.mu.Lock()
   239		defer s.mu.Unlock()
   240		if s.t.Valid() {
   241			return s.t, nil
   242		}
   243		t, err := s.new.Token()
   244		if err != nil {
   245			return nil, err
   246		}
   247		s.t = t
   248		return t, s.f(t)
   249	}
