   251	func (c *microsoftConnector) Refresh(ctx context.Context, s connector.Scopes, identity connector.Identity) (connector.Identity, error) {
   252		if len(identity.ConnectorData) == 0 {
   253			return identity, errors.New("microsoft: no upstream access token found")
   254		}
   255	
   256		var data connectorData
   257		if err := json.Unmarshal(identity.ConnectorData, &data); err != nil {
   258			return identity, fmt.Errorf("microsoft: unmarshal access token: %v", err)
   259		}
   260		tok := &oauth2.Token{
   261			AccessToken:  data.AccessToken,
   262			RefreshToken: data.RefreshToken,
   263			Expiry:       data.Expiry,
   264		}
   265	
   266		client := oauth2.NewClient(ctx, &notifyRefreshTokenSource{
   267			new: c.oauth2Config(s).TokenSource(ctx, tok),
   268			t:   tok,
   269			f: func(tok *oauth2.Token) error {
   270				data := connectorData{
   271					AccessToken:  tok.AccessToken,
   272					RefreshToken: tok.RefreshToken,
   273					Expiry:       tok.Expiry,
   274				}
   275				connData, err := json.Marshal(data)
   276				if err != nil {
   277					return fmt.Errorf("microsoft: marshal connector data: %v", err)
   278				}
   279				identity.ConnectorData = connData
   280				return nil
   281			},
   282		})
   283		user, err := c.user(ctx, client)
   284		if err != nil {
   285			return identity, fmt.Errorf("microsoft: get user: %v", err)
   286		}
   287	
   288		identity.Username = user.Name
   289		identity.Email = user.Email
   290	
   291		if c.groupsRequired(s.Groups) {
   292			groups, err := c.getGroups(ctx, client, user.ID)
   293			if err != nil {
   294				return identity, fmt.Errorf("microsoft: get groups: %v", err)
   295			}
   296			identity.Groups = groups
   297		}
   298	
   299		return identity, nil
   300	}
