   326	func (c *microsoftConnector) user(ctx context.Context, client *http.Client) (u user, err error) {
   327		// https://developer.microsoft.com/en-us/graph/docs/api-reference/v1.0/api/user_get
   328		req, err := http.NewRequest("GET", c.graphURL+"/v1.0/me?$select=id,displayName,userPrincipalName", nil)
   329		if err != nil {
   330			return u, fmt.Errorf("new req: %v", err)
   331		}
   332	
   333		resp, err := client.Do(req.WithContext(ctx))
   334		if err != nil {
   335			return u, fmt.Errorf("get URL %v", err)
   336		}
   337		defer resp.Body.Close()
   338	
   339		if resp.StatusCode != http.StatusOK {
   340			return u, newGraphError(resp.Body)
   341		}
   342	
   343		if err := json.NewDecoder(resp.Body).Decode(&u); err != nil {
   344			return u, fmt.Errorf("JSON decode: %v", err)
   345		}
   346	
   347		return u, err
   348	}
