   358	func (c *microsoftConnector) getGroups(ctx context.Context, client *http.Client, userID string) ([]string, error) {
   359		userGroups, err := c.getGroupIDs(ctx, client)
   360		if err != nil {
   361			return nil, err
   362		}
   363	
   364		if c.groupNameFormat == GroupName {
   365			userGroups, err = c.getGroupNames(ctx, client, userGroups)
   366			if err != nil {
   367				return nil, err
   368			}
   369		}
   370	
   371		// ensure that the user is in at least one required group
   372		filteredGroups := groups_pkg.Filter(userGroups, c.groups)
   373		if len(c.groups) > 0 && len(filteredGroups) == 0 {
   374			return nil, fmt.Errorf("microsoft: user %v not in any of the required groups", userID)
   375		} else if c.useGroupsAsWhitelist {
   376			return filteredGroups, nil
   377		}
   378	
   379		return userGroups, nil
   380	}
