   435	func (c *microsoftConnector) post(ctx context.Context, client *http.Client, reqURL string, in interface{}, out interface{}) (string, error) {
   436		var payload bytes.Buffer
   437	
   438		err := json.NewEncoder(&payload).Encode(in)
   439		if err != nil {
   440			return "", fmt.Errorf("microsoft: JSON encode: %v", err)
   441		}
   442	
   443		req, err := http.NewRequest("POST", reqURL, &payload)
   444		if err != nil {
   445			return "", fmt.Errorf("new req: %v", err)
   446		}
   447		req.Header.Set("Content-Type", "application/json")
   448	
   449		resp, err := client.Do(req.WithContext(ctx))
   450		if err != nil {
   451			return "", fmt.Errorf("post URL %v", err)
   452		}
   453		defer resp.Body.Close()
   454	
   455		if resp.StatusCode != http.StatusOK {
   456			return "", newGraphError(resp.Body)
   457		}
   458	
   459		var next string
   460		if err = json.NewDecoder(resp.Body).Decode(&struct {
   461			NextLink *string     `json:"@odata.nextLink"`
   462			Value    interface{} `json:"value"`
   463		}{&next, out}); err != nil {
   464			return "", fmt.Errorf("JSON decode: %v", err)
   465		}
   466	
   467		return next, nil
   468	}
